#!/usr/bin/env python3
"""Generate Global Intentional Homicide Trends Report (1990-2023)."""

import pandas as pd
import json
import math
from collections import defaultdict

# ── Load data ──────────────────────────────────────────────────────────────
df = pd.read_csv("/app/benchmark/data.csv")

# ── Region mapping via ISO codes ───────────────────────────────────────────
REGION_MAP = {
    # Americas
    "ARG":"Americas","BOL":"Americas","BRA":"Americas","CHL":"Americas","COL":"Americas",
    "CRI":"Americas","CUB":"Americas","DOM":"Americas","ECU":"Americas","SLV":"Americas",
    "GTM":"Americas","GUY":"Americas","HTI":"Americas","HND":"Americas","JAM":"Americas",
    "MEX":"Americas","NIC":"Americas","PAN":"Americas","PRY":"Americas","PER":"Americas",
    "SUR":"Americas","TTO":"Americas","URY":"Americas","VEN":"Americas","BHS":"Americas",
    "BRB":"Americas","BLZ":"Americas","CAN":"Americas","USA":"Americas","PRI":"Americas",
    "ABW":"Americas","AIA":"Americas","ATG":"Americas","BMU":"Americas","VGB":"Americas",
    "CYM":"Americas","CUW":"Americas","DMA":"Americas","GRD":"Americas","GLP":"Americas",
    "GUF":"Americas","MTQ":"Americas","MSR":"Americas","KNA":"Americas","LCA":"Americas",
    "VCT":"Americas","SXM":"Americas","TCA":"Americas","VIR":"Americas",
    # Europe
    "ALB":"Europe","AND":"Europe","AUT":"Europe","BLR":"Europe","BEL":"Europe",
    "BIH":"Europe","BGR":"Europe","HRV":"Europe","CYP":"Europe","CZE":"Europe",
    "DNK":"Europe","EST":"Europe","FIN":"Europe","FRA":"Europe","DEU":"Europe",
    "GRC":"Europe","HUN":"Europe","ISL":"Europe","IRL":"Europe","ITA":"Europe",
    "XKX":"Europe","LVA":"Europe","LIE":"Europe","LTU":"Europe","LUX":"Europe",
    "MLT":"Europe","MDA":"Europe","MCO":"Europe","MNE":"Europe","NLD":"Europe",
    "MKD":"Europe","NOR":"Europe","POL":"Europe","PRT":"Europe","ROU":"Europe",
    "RUS":"Europe","SMR":"Europe","SRB":"Europe","SVK":"Europe","SVN":"Europe",
    "ESP":"Europe","SWE":"Europe","CHE":"Europe","UKR":"Europe","GBR":"Europe",
    "GEO":"Europe","ARM":"Europe","AZE":"Europe","TUR":"Europe",
    # Africa
    "DZA":"Africa","AGO":"Africa","BEN":"Africa","BWA":"Africa","BFA":"Africa",
    "BDI":"Africa","CPV":"Africa","CMR":"Africa","CAF":"Africa","TCD":"Africa",
    "COM":"Africa","COG":"Africa","COD":"Africa","CIV":"Africa","DJI":"Africa",
    "EGY":"Africa","GNQ":"Africa","ERI":"Africa","SWZ":"Africa","ETH":"Africa",
    "GAB":"Africa","GMB":"Africa","GHA":"Africa","GIN":"Africa","GNB":"Africa",
    "KEN":"Africa","LSO":"Africa","LBR":"Africa","LBY":"Africa","MDG":"Africa",
    "MWI":"Africa","MLI":"Africa","MRT":"Africa","MUS":"Africa","MAR":"Africa",
    "MOZ":"Africa","NAM":"Africa","NER":"Africa","NGA":"Africa","RWA":"Africa",
    "STP":"Africa","SEN":"Africa","SYC":"Africa","SLE":"Africa","SOM":"Africa",
    "ZAF":"Africa","SSD":"Africa","SDN":"Africa","TZA":"Africa","TGO":"Africa",
    "TUN":"Africa","UGA":"Africa","ZMB":"Africa","ZWE":"Africa","REU":"Africa",
    "MYT":"Africa",
    # Asia
    "AFG":"Asia","BHR":"Asia","BGD":"Asia","BTN":"Asia","BRN":"Asia",
    "KHM":"Asia","CHN":"Asia","IND":"Asia","IDN":"Asia","IRN":"Asia",
    "IRQ":"Asia","ISR":"Asia","JPN":"Asia","JOR":"Asia","KAZ":"Asia",
    "KWT":"Asia","KGZ":"Asia","LAO":"Asia","LBN":"Asia","MYS":"Asia",
    "MDV":"Asia","MNG":"Asia","MMR":"Asia","NPL":"Asia","OMN":"Asia",
    "PAK":"Asia","PSE":"Asia","PHL":"Asia","QAT":"Asia","SAU":"Asia",
    "SGP":"Asia","KOR":"Asia","LKA":"Asia","SYR":"Asia","TWN":"Asia",
    "TJK":"Asia","THA":"Asia","TLS":"Asia","TKM":"Asia","ARE":"Asia",
    "UZB":"Asia","VNM":"Asia","YEM":"Asia","PRK":"Asia","HKG":"Asia",
    "MAC":"Asia",
    # Oceania
    "AUS":"Oceania","FJI":"Oceania","KIR":"Oceania","MHL":"Oceania",
    "FSM":"Oceania","NRU":"Oceania","NZL":"Oceania","PLW":"Oceania",
    "PNG":"Oceania","WSM":"Oceania","SLB":"Oceania","TON":"Oceania",
    "TUV":"Oceania","VUT":"Oceania","NCL":"Oceania","PYF":"Oceania",
    "GUM":"Oceania","COK":"Oceania",
}

df["region"] = df["iso_code"].map(REGION_MAP).fillna("Other")

# ── Helper filters ─────────────────────────────────────────────────────────
both_all = df[(df["sex"]=="both") & (df["age_group"]=="ALL")].copy()
male_all = df[(df["sex"]=="male") & (df["age_group"]=="ALL")].copy()
female_all = df[(df["sex"]=="female") & (df["age_group"]=="ALL")].copy()

# ══════════════════════════════════════════════════════════════════════════
# SECTION 1: GLOBAL OVERVIEW  ─  KPIs
# ══════════════════════════════════════════════════════════════════════════

# Global median/mean per year
yearly_stats = both_all.groupby("year")["homicide_rate"].agg(["median","mean","count"]).reset_index()
yearly_stats.columns = ["year","median","mean","n_countries"]

# Most recent year with good coverage
latest_year = yearly_stats[yearly_stats["n_countries"] >= 30]["year"].max()
if pd.isna(latest_year):
    latest_year = both_all["year"].max()
latest_data = both_all[both_all["year"]==latest_year]

kpi_global_median = latest_data["homicide_rate"].median()
kpi_global_mean = latest_data["homicide_rate"].mean()
kpi_n_countries_latest = len(latest_data)

# Highest national rate in latest year
highest_row = latest_data.loc[latest_data["homicide_rate"].idxmax()]
kpi_highest_country = highest_row["country"]
kpi_highest_rate = highest_row["homicide_rate"]

# Male-to-female ratio (latest year with both sex data)
def compute_mf_ratio(year):
    m = male_all[male_all["year"]==year]
    f = female_all[female_all["year"]==year]
    merged = m.merge(f, on="country", suffixes=("_m","_f"))
    if len(merged)==0:
        return None, None, 0
    ratio = (merged["homicide_rate_m"] / merged["homicide_rate_f"].replace(0, float("nan"))).dropna()
    return ratio.median(), ratio.mean(), len(ratio)

mf_year = latest_year
mf_median, mf_mean, mf_n = compute_mf_ratio(mf_year)
if mf_n < 10:
    for y in range(int(latest_year)-1, 1989, -1):
        mf_median, mf_mean, mf_n = compute_mf_ratio(y)
        if mf_n >= 10:
            mf_year = y
            break

# Decade-over-decade change
def decade_mean(d_start, d_end):
    sub = both_all[(both_all["year"]>=d_start) & (both_all["year"]<=d_end)]
    return sub["homicide_rate"].mean() if len(sub) > 0 else None

mean_90s = decade_mean(1990, 1999)
mean_00s = decade_mean(2000, 2009)
mean_10s = decade_mean(2010, 2019)
mean_20s = decade_mean(2020, 2023)

def pct_change(old, new):
    if old and new and old != 0:
        return (new - old) / old * 100
    return None

change_90s_00s = pct_change(mean_90s, mean_00s)
change_00s_10s = pct_change(mean_00s, mean_10s)
change_10s_20s = pct_change(mean_10s, mean_20s)

# Reporting coverage: countries per year
total_countries = both_all["country"].nunique()
coverage_latest = kpi_n_countries_latest / total_countries * 100

# ── Time series data for chart ─────────────────────────────────────────────
ts_data = yearly_stats.to_dict("records")

# ══════════════════════════════════════════════════════════════════════════
# SECTION 2: REGIONAL & COUNTRY COMPARISON
# ══════════════════════════════════════════════════════════════════════════

# Top 10 / Bottom 10 by latest year
top10 = latest_data.nlargest(10, "homicide_rate")[["country","homicide_rate","iso_code"]].to_dict("records")
bot10 = latest_data.nsmallest(10, "homicide_rate")[["country","homicide_rate","iso_code"]].to_dict("records")

# Regional aggregates over time
regional_ts = both_all.groupby(["region","year"])["homicide_rate"].agg(["median","mean","count"]).reset_index()
regional_ts.columns = ["region","year","median","mean","n_countries"]

# Regional summary for latest year
regional_latest = both_all[both_all["year"]==latest_year].groupby("region")["homicide_rate"].agg(["median","mean","count"]).reset_index()
regional_latest.columns = ["region","median","mean","n_countries"]
regional_latest = regional_latest.sort_values("mean", ascending=False).to_dict("records")

# ══════════════════════════════════════════════════════════════════════════
# SECTION 3: GENDER DISPARITY
# ══════════════════════════════════════════════════════════════════════════

# Male vs female global medians over time
gender_ts = []
for year in sorted(df["year"].unique()):
    m_rate = male_all[male_all["year"]==year]["homicide_rate"]
    f_rate = female_all[female_all["year"]==year]["homicide_rate"]
    b_rate = both_all[both_all["year"]==year]["homicide_rate"]
    if len(m_rate) >= 5 and len(f_rate) >= 5:
        gender_ts.append({
            "year": int(year),
            "male_median": round(m_rate.median(), 2),
            "female_median": round(f_rate.median(), 2),
            "both_median": round(b_rate.median(), 2),
            "ratio": round(m_rate.median() / max(f_rate.median(), 0.01), 2),
            "n_male": int(len(m_rate)),
            "n_female": int(len(f_rate)),
        })

# Countries with highest gender disparity in latest available data
gender_disp = []
for c in both_all["country"].unique():
    m = male_all[(male_all["country"]==c)].sort_values("year")
    f = female_all[(female_all["country"]==c)].sort_values("year")
    if len(m)==0 or len(f)==0:
        continue
    m_last = m.iloc[-1]
    f_last = f.iloc[-1]
    if m_last["year"] == f_last["year"] and f_last["homicide_rate"] > 0:
        gender_disp.append({
            "country": c,
            "year": int(m_last["year"]),
            "male_rate": round(m_last["homicide_rate"],2),
            "female_rate": round(f_last["homicide_rate"],2),
            "ratio": round(m_last["homicide_rate"] / f_last["homicide_rate"],2),
        })
gender_disp.sort(key=lambda x: x["ratio"], reverse=True)

# ══════════════════════════════════════════════════════════════════════════
# SECTION 4: AGE GROUP ANALYSIS
# ══════════════════════════════════════════════════════════════════════════

age_df = df[(df["sex"]=="both") & (df["age_group"]!="ALL")].copy()
age_summary = age_df.groupby("age_group")["homicide_rate"].agg(["median","mean","count"]).reset_index()
age_summary.columns = ["age_group","median","mean","count"]
age_summary = age_summary.sort_values("mean", ascending=False)

# Age group trends over time (median across countries)
age_ts = age_df.groupby(["age_group","year"])["homicide_rate"].median().reset_index()
age_ts.columns = ["age_group","year","median"]

# Male age group analysis
male_age_df = df[(df["sex"]=="male") & (df["age_group"]!="ALL")].copy()
male_age_summary = male_age_df.groupby("age_group")["homicide_rate"].agg(["median","mean","count"]).reset_index()
male_age_summary.columns = ["age_group","median","mean","count"]

# ══════════════════════════════════════════════════════════════════════════
# SECTION 5: NOTABLE TRENDS & OUTLIERS
# ══════════════════════════════════════════════════════════════════════════

# Countries with largest decrease and increase
country_trends = []
for c in both_all["country"].unique():
    cdata = both_all[both_all["country"]==c].sort_values("year")
    if len(cdata) < 3:
        continue
    first = cdata.iloc[0]
    last = cdata.iloc[-1]
    span = last["year"] - first["year"]
    if span < 5:
        continue
    change = last["homicide_rate"] - first["homicide_rate"]
    pct = (change / first["homicide_rate"] * 100) if first["homicide_rate"] > 0.1 else None
    country_trends.append({
        "country": c,
        "iso_code": first["iso_code"],
        "first_year": int(first["year"]),
        "last_year": int(last["year"]),
        "first_rate": round(first["homicide_rate"], 2),
        "last_rate": round(last["homicide_rate"], 2),
        "abs_change": round(change, 2),
        "pct_change": round(pct, 1) if pct is not None else None,
        "n_obs": int(len(cdata)),
    })

top_improvers = sorted([t for t in country_trends if t["pct_change"] is not None], key=lambda x: x["pct_change"])[:10]
top_deteriorators = sorted([t for t in country_trends if t["pct_change"] is not None], key=lambda x: x["pct_change"], reverse=True)[:10]

# Spike detection: largest single-year jump
spikes = []
for c in both_all["country"].unique():
    cdata = both_all[both_all["country"]==c].sort_values("year")
    if len(cdata) < 2:
        continue
    for i in range(1, len(cdata)):
        prev = cdata.iloc[i-1]
        curr = cdata.iloc[i]
        if curr["year"] - prev["year"] <= 2 and prev["homicide_rate"] > 0.5:
            jump = curr["homicide_rate"] - prev["homicide_rate"]
            pct_jump = jump / prev["homicide_rate"] * 100
            if abs(pct_jump) > 50 and abs(jump) > 2:
                spikes.append({
                    "country": c,
                    "from_year": int(prev["year"]),
                    "to_year": int(curr["year"]),
                    "from_rate": round(prev["homicide_rate"], 2),
                    "to_rate": round(curr["homicide_rate"], 2),
                    "change": round(jump, 2),
                    "pct_change": round(pct_jump, 1),
                })
spikes.sort(key=lambda x: abs(x["pct_change"]), reverse=True)

# ══════════════════════════════════════════════════════════════════════════
# SECTION 6: DATA QUALITY
# ══════════════════════════════════════════════════════════════════════════

coverage_ts = both_all.groupby("year")["country"].nunique().reset_index()
coverage_ts.columns = ["year","n_countries"]

# Countries with most complete data
completeness = both_all.groupby("country")["year"].nunique().reset_index()
completeness.columns = ["country","n_years"]
completeness = completeness.sort_values("n_years", ascending=False)

# Sex-disaggregated coverage
sex_coverage = []
for y in sorted(df["year"].unique()):
    n_m = male_all[male_all["year"]==y]["country"].nunique()
    n_f = female_all[female_all["year"]==y]["country"].nunique()
    n_b = both_all[both_all["year"]==y]["country"].nunique()
    sex_coverage.append({"year": int(y), "both": int(n_b), "male": int(n_m), "female": int(n_f)})

# ══════════════════════════════════════════════════════════════════════════
# BUILD HTML
# ══════════════════════════════════════════════════════════════════════════

def fmt(val, decimals=1):
    if val is None:
        return "N/A"
    return f"{val:,.{decimals}f}"

def pct_fmt(val):
    if val is None:
        return "N/A"
    sign = "+" if val > 0 else ""
    return f"{sign}{val:.1f}%"

def trend_arrow(val):
    if val is None:
        return ""
    return "&#9660;" if val < 0 else "&#9650;"

def trend_color(val, invert=False):
    if val is None:
        return "#6b7280"
    if invert:
        return "#059669" if val > 0 else "#dc2626"
    return "#059669" if val < 0 else "#dc2626"

# Chart data serialization
ts_json = json.dumps(ts_data, default=str)
gender_ts_json = json.dumps(gender_ts, default=str)
regional_ts_json = json.dumps(regional_ts.to_dict("records"), default=str)
coverage_ts_json = json.dumps(coverage_ts.to_dict("records"), default=str)

# Age group data for chart
age_labels_order = ["0_9","10_14","15_17","18_19","20_24","25_29","30_44","45_59","60_PLUS"]
age_label_display = {"0_9":"0–9","10_14":"10–14","15_17":"15–17","18_19":"18–19","20_24":"20–24","25_29":"25–29","30_44":"30–44","45_59":"45–59","60_PLUS":"60+"}
age_chart_data = []
for _, row in age_summary.iterrows():
    ag = row["age_group"]
    if ag in age_labels_order:
        age_chart_data.append({"group": age_label_display.get(ag, ag), "median": round(row["median"],2), "mean": round(row["mean"],2), "count": int(row["count"])})
age_chart_data.sort(key=lambda x: age_labels_order.index(list(age_label_display.keys())[list(age_label_display.values()).index(x["group"])]) if x["group"] in age_label_display.values() else 99)
age_chart_json = json.dumps(age_chart_data, default=str)

# Sex coverage chart data
sex_coverage_json = json.dumps(sex_coverage, default=str)

# Earliest year stats
earliest_yr_data = yearly_stats[yearly_stats["n_countries"] >= 20]
if len(earliest_yr_data) > 0:
    earliest_yr = earliest_yr_data["year"].min()
    earliest_median = earliest_yr_data[earliest_yr_data["year"]==earliest_yr]["median"].values[0]
else:
    earliest_yr = yearly_stats["year"].min()
    earliest_median = yearly_stats.iloc[0]["median"]

overall_change = pct_change(earliest_median, kpi_global_median)

