  .data-table .num {{ text-align: right; font-variant-numeric: tabular-nums; }}
  .rank {{ color: var(--text-light); font-weight: 600; width: 36px; }}

  /* Badges */
  .badge {{
    display: inline-block; padding: 2px 10px; border-radius: 12px;
    font-size: 0.78em; font-weight: 600;
  }}
  .badge-danger {{ background: #fef2f2; color: var(--danger); }}
  .badge-success {{ background: #ecfdf5; color: var(--success); }}
  .badge-warning {{ background: #fffbeb; color: var(--warning); }}
  .badge-info {{ background: #f0f9ff; color: var(--info); }}

  /* Callout */
  .callout {{
    padding: 16px 20px; border-radius: 8px; margin: 16px 0;
    font-size: 0.92em; line-height: 1.6;
  }}
  .callout-info {{ background: #f0f9ff; border-left: 4px solid var(--info); color: #0c4a6e; }}
  .callout-warning {{ background: #fffbeb; border-left: 4px solid var(--warning); color: #78350f; }}
  .callout-danger {{ background: #fef2f2; border-left: 4px solid var(--danger); color: #7f1d1d; }}
  .callout-success {{ background: #ecfdf5; border-left: 4px solid var(--success); color: #064e3b; }}

  /* Insights */
  .insight-box {{
    background: linear-gradient(135deg, #f0f9ff, #eff6ff);
    border: 1px solid #bfdbfe; border-radius: var(--radius);
