  /* Two columns */
  .two-col {{ display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }}
  @media (max-width: 768px) {{ .two-col {{ grid-template-columns: 1fr; }} }}

  /* Prose */
  .prose {{ font-size: 0.95em; color: var(--text); }}
  .prose p {{ margin-bottom: 14px; }}
  .prose ul {{ margin: 12px 0 12px 20px; }}
  .prose li {{ margin-bottom: 6px; }}
  .prose strong {{ font-weight: 600; }}

  /* Footer */
  .report-footer {{
    background: var(--surface-alt); border-top: 1px solid var(--border);
    padding: 32px 0; margin-top: 48px; text-align: center;
    font-size: 0.82em; color: var(--text-muted);
  }}

  /* TOC */
  .toc {{ list-style: none; padding: 0; }}
  .toc li {{ padding: 8px 0; border-bottom: 1px solid var(--border); }}
  .toc li:last-child {{ border-bottom: none; }}
