  .toc a:hover {{ text-decoration: underline; }}
  .toc .toc-num {{ color: var(--text-light); margin-right: 8px; font-weight: 600; }}

  /* Sparkline-style trend indicator */
  .trend-indicator {{ display: inline-flex; align-items: center; gap: 4px; font-weight: 600; font-size: 0.88em; }}
</style>
</head>
